1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: Damage[];
19	};
20	
21	/**
22	 * One type covers both ops, so items/policy/incident are all optional. A
23	 * discriminated union on `op` would express this better, but the spec's
24	 * scenarios are plain object literals whose `op` widens to `string` and so
25	 * would no longer typecheck against literal `"quote"` / `"claim"` variants.
26	 * Revisit if a scenario parser ever narrows `op` on the way in.
27	 */
28	export type Step = {
29	  op: string;
30	  items?: Item[];
31	  policy?: number;
32	  incident?: Incident;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	export type ScenarioResult = {
44	  results: (QuoteResult | ClaimResult)[];
45	};
46	
47	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	/**
56	 * Deliberately NOT derived from the base premiums, though every entry today
57	 * happens to be 10x its counterpart. The MHPCO publishes two independent
58	 * price lists ("Sword: 1000 G insurance value, 100 G base premium"), and the
59	 * rules already pull them apart: the 3-alike building block cuts the base
60	 * premium to 60 G while the insurance value stays 250 G per component. Making
61	 * one a function of the other would encode a coincidence as a rule.
62	 *
63	 * A test now guards this — "caps a policy covering a sword and 3 runes at
64	 * 3500 G". Deriving these values from the base premiums, or routing both
65	 * through a shared summing helper, makes the block rule reach the insurance
66	 * sum and yields a cap of 2120 instead of 3500.
67	 */
68	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	const DEDUCTIBLE = 100;
77	const CAP_MULTIPLE = 2;
78	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
79	const HIGH_ENCHANTMENT_PAYOUT_PERCENT = 50;
80	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
81	const CURSE_SURCHARGE_PERCENT = 50;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
84	const LOYALTY_THRESHOLD_YEARS = 2;
85	const LOYALTY_DISCOUNT_PERCENT = 20;
86	const FOLLOWUP_DISCOUNT_PERCENT = 15;
87	const PROCESSING_FEE = 5;
88	
89	const percentOf = (amount: number, percent: number): number =>
90	  (amount * percent) / 100;
91	
92	/**
93	 * The MHPCO insures only what is on its price list. Looking a type up through
94	 * here rather than indexing a table directly means an unknown type cannot slip
95	 * through as `undefined` and surface later as a NaN premium.
96	 */
97	const priceOf = (
98	  priceList: Record<string, number>,
99	  itemType: string,
100	): number => {
101	  const price = priceList[itemType];
102	  if (price === undefined) {
103	    throw new Error(`unknown item type: ${itemType}`);
104	  }
105	  return price;
106	};
107	
108	/**
109	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
110	 * the opposite direction, so this deliberately names the premium case only
111	 * rather than a general "in the MHPCO's favour" rounding.
112	 */
113	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
114	
115	const BLOCK_SIZE = 3;
116	const BLOCK_BASE_PREMIUM = 60;
117	
118	/**
119	 * Tallies how often each key occurs. Shared by the two things the MHPCO counts
120	 * by type — the items ON a policy and the damages claimed AGAINST it — which
121	 * are different domain concepts over different shapes, but genuinely the same
122	 * counting. The key is supplied by the caller precisely so neither concept has
123	 * to borrow the other's field name.
124	 */
125	const countByKey = <T>(values: T[], keyOf: (value: T) => string): Map<string, number> =>
126	  values.reduce(
127	    (counts, value) =>
128	      counts.set(keyOf(value), (counts.get(keyOf(value)) ?? 0) + 1),
129	    new Map<string, number>(),
130	  );
131	
132	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
133	const countAlikeItems = (items: Item[]): Map<string, number> =>
134	  countByKey(items, (item) => item.type);
135	
136	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
137	
138	const basePremiumForAlikeItems = (type: string, count: number): number =>
139	  formsBuildingBlock(count)
140	    ? BLOCK_BASE_PREMIUM
141	    : count * priceOf(BASE_PREMIUM_BY_ITEM_TYPE, type);
142	
143	const policyBasePremium = (items: Item[]): number =>
144	  [...countAlikeItems(items)].reduce(
145	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
146	    0,
147	  );
148	
149	const itemBasePremium = (item: Item): number =>
150	  priceOf(BASE_PREMIUM_BY_ITEM_TYPE, item.type);
151	
152	/**
153	 * An absent `enchantment` reads as 0 — a plain rune is not enchanted at all.
154	 * The threshold is a parameter because the MHPCO sets two different bars: 5
155	 * for the premium surcharge, 8 for the payout clause.
156	 */
157	const enchantmentAtLeast = (item: Item, threshold: number): boolean =>
158	  (item.enchantment ?? 0) >= threshold;
159	
160	const isHighlyEnchanted = (item: Item): boolean =>
161	  enchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD);
162	
163	/** Item-specific surcharges stack additively. */
164	const itemSurchargePercent = (item: Item): number =>
165	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
166	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
167	
168	/**
169	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
170	 * premium — unlike policy-wide modifiers, which apply to the policy base.
171	 */
172	const totalItemSurcharges = (items: Item[]): number =>
173	  items.reduce(
174	    (total, item) =>
175	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
176	    0,
177	  );
178	
179	const isLongStanding = (customer: Customer): boolean =>
180	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
181	
182	/**
183	 * The net of all policy-wide percentages. Policy-wide modifiers are
184	 * percentages of the POLICY base premium — unlike item-specific modifiers,
185	 * which apply to the affected item's own base. The net is negative when the
186	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
187	 */
188	const netPolicyAdjustmentPercent = (
189	  customer: Customer,
190	  precedingSteps: number,
191	): number =>
192	  FIRST_INSURANCE_SURCHARGE_PERCENT -
193	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
194	  // The follow-up discount is owed on every quote after the customer's FIRST
195	  // QUOTE, but what we have here is a count of preceding STEPS. The two
196	  // coincide only because every step exercised so far is a quote; once claim
197	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
198	  // as a second follow-up. No test forces the distinction yet.
199	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
200	
201	const policyAdjustment = (
202	  policyBase: number,
203	  customer: Customer,
204	  precedingSteps: number,
205	): number =>
206	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
207	
208	const quotePremium = (
209	  items: Item[],
210	  customer: Customer,
211	  precedingSteps: number,
212	): number => {
213	  const basePremium = policyBasePremium(items);
214	  return roundPremiumUp(
215	    basePremium +
216	      totalItemSurcharges(items) +
217	      policyAdjustment(basePremium, customer, precedingSteps) +
218	      PROCESSING_FEE,
219	  );
220	};
221	
222	const roundPayoutDown = (payout: number): number => Math.floor(payout);
223	
224	/**
225	 * Goes through `priceOf` for the same reason the premium side does: an unknown
226	 * type would otherwise index to `undefined` and sum to a NaN cap, which
227	 * `Math.min` would carry into a NaN payout instead of an error. This is a
228	 * guarded lookup, not a derivation — the two price lists stay independent.
229	 */
230	const insuranceSum = (items: Item[]): number =>
231	  items.reduce(
232	    (sum, item) => sum + priceOf(INSURANCE_VALUE_BY_ITEM_TYPE, item.type),
233	    0,
234	  );
235	
236	/**
237	 * The MHPCO settles damage only to what it insures. Throwing here rather than
238	 * returning undefined means an uninsured item cannot be quietly paid out.
239	 *
240	 * ONE check covers both halves of the spec's error bullet, and two tests now
241	 * hold it there: "rejects a claim whose damage references an item not covered
242	 * by the policy" (amulet damage against a sword-only policy) and "rejects a
243	 * claim whose damage references an unknown item type" (broomstick). The second
244	 * needed no code — an unknown type is a strict subset of "not among the
245	 * policy's items", since nothing unknown can be on a policy in the first place;
246	 * a quote naming one is rejected by `priceOf` before any claim can reference it.
247	 *
248	 * Do NOT route this through `priceOf` to unify the two "unknown item" errors.
249	 * The domains differ: an amulet is a perfectly KNOWN type, so `priceOf` would
250	 * return 600 and the uninsured-amulet claim would silently pay out. Membership
251	 * in this policy, not membership on the price list, is the question here.
252	 */
253	const damagedItem = (damage: Damage, policyItems: Item[]): Item => {
254	  const item = policyItems.find((it) => it.type === damage.itemType);
255	  if (item === undefined) {
256	    throw new Error(`item not covered by the policy: ${damage.itemType}`);
257	  }
258	  return item;
259	};
260	
261	/**
262	 * What the MHPCO reimburses for ONE damaged item, before the deductible.
263	 * Highly enchanted items are reimbursed at half the damage amount.
264	 *
265	 * NOT A BUG: the spec's "dragon material is fully reimbursed" clause is
266	 * deliberately absent, because no example can observe it. Full reimbursement is
267	 * already what happens when no clause fires, so below enchantment 8 a dragon
268	 * item is indistinguishable from a steel one; at enchantment >= 8 the spec says
269	 * the 50 % rule wins, so dragon is indistinguishable again. The clause has no
270	 * input that would change an output — adding it would be unfalsifiable by the
271	 * suite. Both dragon tests below pass against this code for exactly the reasons
272	 * their comments state. If a future rule ever makes material observable (say, a
273	 * dragon-only exemption from the deductible, or a clause the 50 % rule does not
274	 * override), add it then, driven by that example.
275	 *
276	 * The enchantment is read from the FIRST policy item of the damaged type — see
277	 * `damagedItem`, which throws if the policy covers no such type at all. Since
278	 * `rejectSurplusDamages` now bounds the damages of a type by the number
279	 * insured, the remaining gap is narrow: a policy holding alike items that
280	 * DIFFER in enchantment, damaged within that count, reimburses every one of
281	 * them at the first item's enchantment. Two enchantment-9 swords are settled
282	 * correctly; an enchantment-9 and an enchantment-3 sword are not. Pairing each
283	 * damage with a distinct item needs an example that says which one a claim
284	 * refers to, and the spec's damages name only a type.
285	 */
286	const reimbursementFor = (damage: Damage, policyItems: Item[]): number =>
287	  enchantmentAtLeast(
288	    damagedItem(damage, policyItems),
289	    HIGH_ENCHANTMENT_PAYOUT_THRESHOLD,
290	  )
291	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_PAYOUT_PERCENT)
292	    : damage.amount;
293	
294	/**
295	 * One damaged item's contribution to the payout. The deductible comes off ONCE
296	 * PER DAMAGED ITEM, not once per incident — expressing it at the level of a
297	 * single damage is what makes that per-item scope structural rather than a
298	 * remark about where a subtraction happens to sit.
299	 */
300	const payoutForDamage = (damage: Damage, policyItems: Item[]): number =>
301	  reimbursementFor(damage, policyItems) - DEDUCTIBLE;
302	
303	/**
304	 * The MHPCO will not pay twice for one insured item. Two sword damages against
305	 * a single insured sword is a malformed claim, not a double loss — and the
306	 * spec rejects the WHOLE claim rather than dropping the surplus entry, so this
307	 * is checked up front for the entire incident before anything is paid.
308	 */
309	const rejectSurplusDamages = (incident: Incident, policyItems: Item[]): void => {
310	  const covered = countAlikeItems(policyItems);
311	  const claimed = countByKey(incident.damages, (damage) => damage.itemType);
312	
313	  for (const [itemType, count] of claimed) {
314	    if (count > (covered.get(itemType) ?? 0)) {
315	      throw new Error(`more ${itemType} damages than the policy covers`);
316	    }
317	  }
318	};
319	
320	/**
321	 * A negative loss is not a loss. Left unchecked such an entry would not merely
322	 * misprice the claim: it subtracts from the payout and so ADDS to the policy's
323	 * remaining cap, letting a claimant raise their own ceiling.
324	 */
325	const rejectNegativeDamages = (incident: Incident): void => {
326	  for (const damage of incident.damages) {
327	    if (damage.amount < 0) {
328	      throw new Error(`damage amount cannot be negative: ${damage.amount}`);
329	    }
330	  }
331	};
332	
333	/**
334	 * The whole incident's payout, before rounding — the per-item payouts summed.
335	 * NOT named for reimbursement: `reimbursementFor` is the amount BEFORE the
336	 * deductible, and reusing that word here would invite a reader to subtract it
337	 * a second time.
338	 */
339	const payoutBeforeRounding = (
340	  incident: Incident,
341	  policyItems: Item[],
342	): number => {
343	  rejectNegativeDamages(incident);
344	  rejectSurplusDamages(incident, policyItems);
345	  return incident.damages.reduce(
346	    (total, damage) => total + payoutForDamage(damage, policyItems),
347	    0,
348	  );
349	};
350	
351	/**
352	 * Anything that is not a claim is treated as a quote, which is why this names
353	 * the claim case rather than offering an `isQuote` counterpart: a two-sided
354	 * pair would imply a third possibility the code does not handle. See the Step
355	 * doc comment on why `op` is a plain string.
356	 */
357	const isClaim = (step: Step): boolean => step.op === "claim";
358	
359	/** A claim's `policy` field is the index of the quote step that wrote it. */
360	const itemsCoveredBy = (policy: number, scenario: Scenario): Item[] =>
361	  scenario.steps[policy].items ?? [];
362	
363	/** The MHPCO caps a policy at twice its insurance sum. */
364	const capFor = (policyItems: Item[]): number =>
365	  CAP_MULTIPLE * insuranceSum(policyItems);
366	
367	/**
368	 * A policy's cap is consumed cumulatively: each payout draws down what remains,
369	 * and a claim can never pay out more than is left. The clamp is applied AFTER
370	 * rounding, so a fractional payout cannot round its way past the remaining cap.
371	 *
372	 * Takes the policy's items and its remaining cap rather than looking either up,
373	 * which keeps the arithmetic of a single claim free of the ledger's bookkeeping.
374	 * `capLedger.settle` resolves both and is the only caller.
375	 */
376	const settleClaim = (
377	  incident: Incident,
378	  policyItems: Item[],
379	  remainingBefore: number,
380	): ClaimResult => {
381	  const desired = roundPayoutDown(payoutBeforeRounding(incident, policyItems));
382	  const payout = Math.min(desired, remainingBefore);
383	  return { payout, remainingCap: remainingBefore - payout };
384	};
385	
386	/**
387	 * Tracks what each policy has left of its cap as claims land against it, and
388	 * settles claims against it. A policy is seeded from its items the first time
389	 * it is claimed against, which is why this needs the scenario: the cap is a
390	 * property of the covered items, and those live in the quote step the claim
391	 * points at.
392	 *
393	 * Settling lives here rather than in the caller because the drawdown is the
394	 * whole reason the ledger exists: reading what remains, paying out of it, and
395	 * writing back what is left are one indivisible step, and a caller that could
396	 * read without writing back could silently let a policy pay twice over.
397	 */
398	const capLedger = (scenario: Scenario) => {
399	  const remainingByPolicy = new Map<number, number>();
400	
401	  return {
402	    settle: (policy: number, incident: Incident): ClaimResult => {
403	      const policyItems = itemsCoveredBy(policy, scenario);
404	      const remainingBefore =
405	        remainingByPolicy.get(policy) ?? capFor(policyItems);
406	      const result = settleClaim(incident, policyItems, remainingBefore);
407	      remainingByPolicy.set(policy, result.remainingCap);
408	      return result;
409	    },
410	  };
411	};
412	
413	/**
414	 * Steps are processed in order because claims draw down a policy's remaining
415	 * cap, so each result depends on the claims before it.
416	 */
417	export const runScenario = (scenario: Scenario): ScenarioResult => {
418	  const caps = capLedger(scenario);
419	
420	  const results = scenario.steps.map((step, precedingSteps) => {
421	    if (isClaim(step)) {
422	      // Non-null: only claim steps reach here, and every claim carries an
423	      // incident. See the Step doc comment.
424	      return caps.settle(step.policy ?? 0, step.incident!);
425	    }
426	
427	    return {
428	      premium: quotePremium(step.items ?? [], scenario.customer, precedingSteps),
429	    };
430	  });
431	
432	  return { results };
433	};
